-- Generated by packages/db/tests/run-db-baseline-replay.mjs --write-built from the database built from repository files.
-- Do not edit by hand; see packages/db/functions/README.md.

-- runtime_work_items(uuid,uuid)
CREATE OR REPLACE FUNCTION public.runtime_work_items(p_actor_id uuid, p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE s runtime_sessions; result jsonb;
BEGIN
 PERFORM bill2_actor(p_actor_id);
 SELECT * INTO s FROM runtime_sessions WHERE id=p_session_id AND actor_id=p_actor_id;
 IF s.id IS NULL OR s.content_deleted_at IS NOT NULL OR s.erased_at IS NOT NULL
  OR NOT coalesce(bill2_scope_allowed(p_actor_id,s.scope),false) THEN RAISE EXCEPTION 'RUNTIME_SCOPE_DENIED'; END IF;
 -- The same fence as runtime_view: an answer it hides (an unavailable_reason, or one that fails runtime_history_availability)
 -- shows no work rows either.
 WITH availability AS MATERIALIZED (
  SELECT a.execution_id id,a.available FROM runtime_history_availability(ARRAY(
   SELECT e.id FROM runtime_executions e JOIN bill2_runs b ON b.id=e.billing_run_id WHERE e.session_id=s.id)) a
 )
 SELECT coalesce(jsonb_object_agg(g.execution_id::text,g.items),'{}'::jsonb) INTO result FROM (
  SELECT r.execution_id,jsonb_agg(r.item||jsonb_build_object('id',r.call_id) ORDER BY r.rank,r.call_id) items FROM (
   SELECT t.execution_id,t.call_id,w.rank,w.item,row_number() OVER (PARTITION BY t.execution_id ORDER BY w.rank,t.call_id) n
   FROM runtime_executions e
   JOIN runtime_tool_calls t ON t.execution_id=e.id AND t.name='read_source' AND t.erased_at IS NULL
   CROSS JOIN LATERAL (
    SELECT * FROM (VALUES (
     CASE
      WHEN t.result->>'kind'='workspace_source' AND t.result#>>'{identity,kind}'='positioning' THEN 1
      WHEN t.result->>'kind'='workspace_source' AND t.result#>>'{identity,kind}'='benchmarks' THEN 2
      WHEN t.result->>'kind'='library_search' THEN 3
      WHEN t.result->>'kind'='library_segment' THEN 4
      -- B2 own-post work projection
      WHEN t.result->>'kind'='my_posts' THEN 5
      WHEN t.result->>'kind'='unavailable' AND t.result->>'reason' IN ('capacity_exhausted','read_limit') AND e.payload->>'ownPosts'='true'
       AND t.arguments->>'query' IN ('my_posts','my_posts:14','my_posts:30','my_posts:90') THEN 5
      WHEN t.result IS NULL AND e.state IN ('prepared','running','interrupted','waiting_credits','waiting_resume') AND e.payload->>'ownPosts'='true'
       AND t.arguments->>'query' IN ('my_posts','my_posts:14','my_posts:30','my_posts:90') THEN 5
      WHEN t.result IS NULL AND e.state IN ('prepared','running') AND t.arguments->>'query' LIKE 'search:%' THEN 3
      WHEN t.result IS NULL AND e.state IN ('prepared','running') AND t.arguments->>'query' LIKE 'doc-%' THEN 4
     END,
     CASE
      WHEN t.result->>'kind'='workspace_source' AND t.result#>>'{identity,kind}'='positioning' THEN
       jsonb_build_object('kind','positioning','state','done','label','读了你确认的定位','detail',left(t.result#>>'{identity,name}',80))
      WHEN t.result->>'kind'='workspace_source' AND t.result#>>'{identity,kind}'='benchmarks' THEN
       jsonb_build_object('kind','my_benchmarks','state','done','label','看了你的对标账号数据')
      WHEN t.result->>'kind'='unavailable' AND t.result->>'reason' IN ('capacity_exhausted','read_limit') THEN
       jsonb_build_object('kind','my_posts','state','missing','label',CASE t.result->>'reason'
        WHEN 'read_limit' THEN '本条回答的作品读取次数已用完' ELSE '资料太多放不下，先按已读到的回答' END)
      WHEN t.result->>'kind'='my_posts' THEN jsonb_build_object('kind','my_posts','state',CASE
       WHEN t.result->>'status'='available' AND jsonb_typeof(t.result->'posts')='array'
        AND t.result->>'window_days' IN ('14','30','90') THEN 'done'
       WHEN t.result->>'status' IN ('not_connected','no_entitlement','no_recent_posts') THEN 'missing' ELSE 'pending' END,
       'label',CASE t.result->>'status'
        WHEN 'not_connected' THEN '未取到：还没有连接账号'
        WHEN 'no_entitlement' THEN '读你的作品数据是 Pro/Gold 会员功能，这次先按定位和资料回答'
        WHEN 'no_recent_posts' THEN CASE WHEN t.result->>'window_days' IN ('14','30','90')
         THEN '最近 '||(t.result->>'window_days')||' 天没有新作品' ELSE '作品数据待核实' END
        WHEN 'stale' THEN CASE WHEN t.result->>'as_of' ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
         THEN '数据截至 '||(t.result->>'as_of')||'，最近一次快照已超过 3 天。' ELSE '还没有取到作品快照，指标未取到。' END
        WHEN 'available' THEN CASE WHEN jsonb_typeof(t.result->'posts')='array' AND t.result->>'window_days' IN ('14','30','90')
         THEN '读了你最近 '||(t.result->>'window_days')||' 天的 '||jsonb_array_length(t.result->'posts')||' 条作品'
         ELSE '作品数据待核实' END ELSE '作品数据待核实' END)
      WHEN t.result->>'kind'='library_search' THEN (
       SELECT CASE WHEN count(*)>0 THEN jsonb_build_object('kind','library_search','state','done',
         'label','在资料库里找到 '||count(*)||' 篇相关内容','detail',left(string_agg(title,'、' ORDER BY title),120))
        ELSE jsonb_build_object('kind','library_search','state','missing','label','资料库里没找到相关内容',
         'detail',left('搜索词：'||coalesce((SELECT string_agg(w2,' ') FROM jsonb_array_elements_text(coalesce(t.result->'terms','[]')) w2),''),120)) END
       FROM (SELECT DISTINCT h->>'documentId' doc,left(coalesce(nullif(h->>'title',''),'（未命名）'),60) title
        FROM jsonb_array_elements(coalesce(t.result->'hits','[]')) h) d)
      WHEN t.result->>'kind'='library_segment' THEN
       jsonb_build_object('kind','library_read','state','done','label','读了一段资料','detail',left(t.result->>'title',80))
      WHEN t.result IS NULL AND t.arguments->>'query' IN ('my_posts','my_posts:14','my_posts:30','my_posts:90') THEN
       jsonb_build_object('kind','my_posts','state',CASE WHEN e.state IN ('prepared','running') THEN 'running' ELSE 'pending' END,
        'label',CASE WHEN e.state IN ('prepared','running') THEN '' ELSE '作品读取待核实' END)
      WHEN t.result IS NULL AND t.arguments->>'query' LIKE 'search:%' THEN
       jsonb_build_object('kind','library_search','state','running','label','')
      WHEN t.result IS NULL THEN jsonb_build_object('kind','library_read','state','running','label','')
     END)) v(rank,item) WHERE v.rank IS NOT NULL) w
   JOIN availability av ON av.id=e.id AND av.available
   WHERE e.session_id=s.id AND e.actor_id=p_actor_id AND e.erased_at IS NULL AND e.content_deleted_at IS NULL
    AND e.unavailable_reason IS NULL
    AND (t.result IS NULL OR t.result->>'kind' IS DISTINCT FROM 'my_posts' OR runtime_workspace_posts_visible(p_actor_id,t.result))
    AND (t.result IS NULL OR t.result->>'kind' NOT IN ('library_search','library_segment')
     -- revision-stable library work rows
     OR (t.result->>'kind'='library_search' AND NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(coalesce(t.result->'hits','[]'::jsonb)) h
      WHERE NOT EXISTS (SELECT 1 FROM runtime_library_references rf
       JOIN library_documents d ON d.id=rf.document_id AND d.actor_id=rf.actor_id
       WHERE rf.execution_id=e.id AND rf.actor_id=p_actor_id AND rf.document_id::text=h->>'documentId'
        AND rf.content_version::text=h->>'version' AND d.deleted_at IS NULL AND d.status='ready')))
     OR (t.result->>'kind'='library_segment' AND EXISTS (
      SELECT 1 FROM runtime_library_references rf
      JOIN library_documents d ON d.id=rf.document_id AND d.actor_id=rf.actor_id
      WHERE rf.execution_id=e.id AND rf.actor_id=p_actor_id AND rf.document_id::text=t.result->>'documentId'
       AND rf.content_version::text=t.result->>'version' AND d.deleted_at IS NULL AND d.status='ready')))
  ) r WHERE r.n<=12 GROUP BY r.execution_id
 ) g;
 -- free chat research rows
 WITH answers AS MATERIALIZED (
  SELECT e.id FROM runtime_executions e
  WHERE e.session_id=s.id AND e.actor_id=p_actor_id AND e.erased_at IS NULL AND e.content_deleted_at IS NULL
   AND e.unavailable_reason IS NULL AND e.payload->'research'->>'freeChat'='free-chat-v1'
 ), visible AS MATERIALIZED (
  SELECT a.execution_id id FROM runtime_history_availability(ARRAY(SELECT id FROM answers)) a WHERE a.available
 )
 SELECT coalesce(result,'{}'::jsonb)||coalesce(jsonb_object_agg(k.execution_id::text,
   coalesce(result->(k.execution_id::text),'[]'::jsonb)||k.items),'{}'::jsonb) INTO result FROM (
  SELECT r.execution_id,jsonb_agg(r.item ORDER BY r.created_at,r.id) items FROM (
   SELECT p.execution_id,o.id,o.created_at,row_number() OVER (PARTITION BY p.execution_id ORDER BY o.created_at,o.id) n,
    jsonb_build_object('id',o.id,'kind','research',
     'state',CASE WHEN o.state IN ('prepared','dispatched') THEN 'running' WHEN o.state='unknown' THEN 'pending'
      WHEN o.state='succeeded' AND o.result->>'outcome' IN ('ok','partial') THEN 'done' ELSE 'missing' END,
     'label',left('搜索 '||coalesce(o.result->'call'->>'query',''),200),
     'research',jsonb_build_object('callId',o.id,'toolName',o.result->>'toolName','args','{}'::jsonb,
      'query',left(coalesce(o.result->'call'->>'query',''),200),'platform',o.result->'call'->>'platform',
      'dataKind',o.result->'call'->>'dataKind',
      'state',CASE WHEN o.state IN ('prepared','dispatched') THEN 'running' WHEN o.state='unknown' THEN 'unknown'
       WHEN o.state='succeeded' AND o.result->>'outcome' IN ('ok','partial') THEN 'succeeded' ELSE 'failed' END,
      'credits',CASE WHEN c.settled_at IS NOT NULL AND c.nominal_source LIKE 'tool_%'
       THEN (c.nominal_cost_usd*bill2_unit_multiplier(c.payload->'billingUnit'->'multiplier')*b.credits_per_usd)::text END)) item
   FROM visible v
   JOIN research_plans p ON p.execution_id=v.id AND p.actor_id=p_actor_id AND p.session_id=s.id AND p.erased_at IS NULL
   JOIN research_operations o ON o.plan_id=p.id AND o.erased_at IS NULL
   LEFT JOIN bill2_calls c ON c.id=o.bill2_call_id AND c.call_kind='tool'
   LEFT JOIN bill2_runs b ON b.id=c.run_id AND b.actor_id=p_actor_id
  ) r WHERE r.n<=12 GROUP BY r.execution_id
 ) k;
 RETURN result;
END $function$;
